# area: gradual_any
# hypothesis: Any propagates through a call and is accepted where int is expected, so mypy and ty infer Any for the loaded value and accept assert_type(total(got), int), while the attribute access on an object-typed parameter is rejected and CPython raises AttributeError, which the guard catches.
from typing import Any, assert_type, reveal_type


def load(raw: Any) -> Any:
    return raw["count"]


def total(n: int) -> int:
    return n + 1


def inspect_object(o: object) -> int:
    return o.bit_length()  # expect-error


raw_value: Any = {"count": 4}
got = load(raw_value)
reveal_type(got)
assert_type(total(got), int)
print(total(got))

plain: object = "three"
try:
    print(inspect_object(plain))
except AttributeError:
    print("AttributeError on object")
